import sys

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    nums = list(map(int, data))
    if len(nums) < 2:
        return
    n = len(nums)
    first = nums[0]
    second = None
    if nums[1] != first:
        if nums[1] > first:
            second = first
            first = nums[1]
        else:
            second = nums[1]
    else:
        # first two are same, need to find second largest (which differs from first)
        for i in range(2, n):
            v = nums[i]
            if v != first:
                if second is None or v > second:
                    second = v
                break
    for i in range(2 if second is not None else 0, n):
        v = nums[i]
        if v == first:
            continue
        if second is None or v > second:
            second = v
    if second is not None and second != first:
        print(second)

if __name__ == '__main__':
    main()
